import {reviewPreview} from './reviews-preview.mjs';
import {servicesHero} from './services-hero.mjs';
import {servicePackages} from './service-packages.mjs';
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const dist=path.join(root,'dist');
const data=JSON.parse(fs.readFileSync(path.join(root,'src/content.json'),'utf8'));
const reviewData=JSON.parse(fs.readFileSync(path.join(root,'src/reviews.json'),'utf8'));
const reviewProfiles=new Map(reviewData.profiles.map(profile=>[profile.id,profile]));
const aiService=data.services.find(service=>service.slug==='ai-automation');
const projects=JSON.parse(fs.readFileSync(path.join(root,'src/case-studies.json'),'utf8'));
const designCatalog=path.join(root,'src/portfolio-designs.json');
const designProjects=fs.existsSync(designCatalog)?JSON.parse(fs.readFileSync(designCatalog,'utf8')):[];
if(!Array.isArray(designProjects))throw new Error('portfolio-designs.json must contain a project array.');
const projectSlugs=new Set(projects.map(p=>p.slug));
for(const project of designProjects){
 if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(project.slug||''))throw new Error('A portfolio design has an invalid slug.');
 if(projectSlugs.has(project.slug))throw new Error('Duplicate portfolio slug: '+project.slug);
 const validCover=sourceOnlyPreview(project.cover)?Boolean(project.cover.nodeId&&(project.cover.figmaUrl||project.figmaUrl)):Boolean(project.cover?.src&&project.cover.width>0&&project.cover.height>0);
 if(!project.name||!project.summary||!validCover)throw new Error('Incomplete portfolio design: '+project.slug);
 if(!['ui','ui-development','development','template'].includes(project.scope))throw new Error('Unsupported portfolio scope: '+project.slug);
 projectSlugs.add(project.slug);
}
const allProjects=[...projects,...designProjects];
const base='https://aptechagency.com';
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paragraphs=items=>items.map(text=>`<p>${h(text)}</p>`).join('');
const list=items=>items.map(text=>`<li>${h(text)}</li>`).join('');
const link=(url,label,classes='button')=>`<a class="${classes}" href="${h(url)}">${h(label)}</a>`;
const buttonRow=items=>`<div class="button-row">${items.join('')}</div>`;
const eyebrow=text=>`<p class="eyebrow">${h(text)}</p>`;
const icon=(name,cls='')=>{
 const paths={
  'website-development':'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18M7 6.5h.01M10 6.5h.01m-1 6-3 2.5 3 2.5m6-5 3 2.5-3 2.5"/>',
  wordpress:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M4 8h16m-11 0v13m3-9h5m-5 4h5"/>',
  'ui-ux-design':'<path d="M4 4h6v6H4zm10 10h6v6h-6zM14 4h6v6h-6zM4 14h6v6H4z"/>',
  ecommerce:'<path d="M3 4h2l3 12h10l3-9H6m3 9-1 3h11"/><circle cx="10" cy="21" r=".7"/><circle cx="17" cy="21" r=".7"/>',
  'ai-automation':'<rect x="3" y="9" width="5" height="6" rx="1"/><rect x="16" y="3" width="5" height="6" rx="1"/><rect x="16" y="15" width="5" height="6" rx="1"/><path d="M8 12h4V6h4m-4 6v6h4"/>',
  'website-care':'<path d="m12 3 8 3v6c0 4-8 9-8 9s-8-5-8-9V6z"/><path d="m8 12 3 3 5-6"/>',
  moon:'<path d="M20.5 13.1A8.7 8.7 0 0 1 10.9 3.5a8.8 8.8 0 1 0 9.6 9.6Z"/>',
  sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M4.9 4.9l1.4 1.4m11.4 11.4 1.4 1.4M4.9 19.1l1.4-1.4M17.7 6.3l1.4-1.4"/>',
  chat:'<path d="M20.5 11.5a8.5 8.5 0 0 1-8.5 8.5 9.1 9.1 0 0 1-3.9-.9L3 21l1.5-5a8.5 8.5 0 1 1 16-4.5Z"/><path d="M8 10h8m-8 4h5"/>',
  phone:'<path d="M8 3H4a1 1 0 0 0-1 1c0 9.4 7.6 17 17 17a1 1 0 0 0 1-1v-4l-5-2-2 2a14 14 0 0 1-6-6l2-2z"/>',
  calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h3m2 0h3m-8 3h3"/>',
  lead:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m1-11 3 3 3-3m-3 3V5"/>',
  close:'<path d="m6 6 12 12M18 6 6 18"/>',
  review:'<path d="M8 3h8l4 4v14H4V3zM16 3v5h4m-12 5 3 3 5-6"/>',
  message:'<path d="M3 5h18v14H3zM3 5l9 7 9-7"/>'
 };
 return `<svg${cls?` class="${cls}"`:''} viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths['website-development']}</svg>`;
};
