const controls=()=>`<button class="page-control theme-toggle" id="theme-toggle" type="button" aria-label="Switch to night mode" aria-pressed="false" title="Switch to night mode" hidden>${icon('moon','theme-moon')}${icon('sun','theme-sun')}</button><button class="page-control chat-launcher" id="chat-launcher" type="button" aria-label="Open WhatsApp message" aria-controls="chat-panel" aria-expanded="false" hidden>${icon('chat')}<span>WhatsApp</span></button><section class="chat-panel" id="chat-panel" role="dialog" aria-modal="false" aria-labelledby="chat-title" hidden><div class="chat-panel-head"><div><p class="chat-kicker">AP TECH · WHATSAPP</p><h2 id="chat-title">Let’s talk.</h2></div><button class="chat-close" id="chat-close" type="button" aria-label="Close WhatsApp message">${icon('close')}</button></div><div class="chat-panel-body"><p class="chat-intro">${h(data.chat.intro)}</p><div class="chat-topics" role="group" aria-label="Choose a conversation topic">${data.chat.topics.map(t=>`<button type="button" data-chat-topic="${h(t.value)}" aria-pressed="false">${h(t.label)}</button>`).join('')}</div><label for="chat-message">Your message</label><textarea id="chat-message" rows="3" maxlength="2000" placeholder="${h(data.chat.messagePlaceholder)}"></textarea><a class="button" id="chat-whatsapp" href="https://wa.me/8801799664826" target="_blank" rel="noopener noreferrer">Continue on WhatsApp</a><p class="chat-channel-note">Opens WhatsApp. Review your message before sending.</p><a class="chat-email" href="mailto:info@aptechagency.com">Prefer email?</a></div></section>`;
