const aiConnections=()=>`<section class="section surface-alt"><div class="wrap"><div class="section-head"><div>${eyebrow('From question to action')}<h2>From a question<br><em>to the next step.</em></h2></div><p class="lead">Your chat, phone, calendar and customer records should work together. We connect the tools you use and set clear rules for what AI can do.</p></div><div class="ai-flow"><article><span>${icon('chat')}</span><h3>Listen &amp; answer</h3><p>Answer questions using business information you have approved.</p></article><article><span>${icon('lead')}</span><h3>Capture the details</h3><p>Collect the details for an enquiry, order, booking or callback.</p></article><article><span>${icon('review')}</span><h3>Confirm the action</h3><p>Check the details and confirm an action only after your system accepts it.</p></article><article><span>${icon('ai-automation')}</span><h3>Keep your team informed</h3><p>Update your records and send summaries or anything that needs attention to the right person.</p></article></div></div></section>`;
const aiDelivery=()=>`<section class="section surface-alt"><div class="wrap"><div class="section-head"><div>${eyebrow('Built around your business')}<h2>The care behind<br><em>the automation.</em></h2></div></div><div class="principle-grid">${aiService.deliveryNotes.map(n=>`<article class="principle"><h3>${h(n.title)}</h3><p>${h(n.text)}</p></article>`).join('')}</div></div></section>`;

const reviewDate=value=>new Date(`${value}T00:00:00Z`).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const reviewCard=(review,hidden=false)=>{
 const profile=reviewProfiles.get(review.profileId);
 if(!profile)throw new Error('Missing review source profile: '+review.profileId);
 const stars='★'.repeat(Math.floor(review.score))+'☆'.repeat(5-Math.floor(review.score));
 return `<article class="review-card" data-review-card${hidden?' hidden':''} aria-label="Review by ${h(review.reviewer)}"><div class="review-card-top"><span class="review-stars" role="img" aria-label="${h(review.score)} out of 5"><span aria-hidden="true">${stars}</span></span><span class="review-platform">${h(review.score)}/5 · Fiverr</span></div><blockquote class="review-quote"><p>“${h(review.quote)}”</p></blockquote><div class="review-person"><span class="review-initial" aria-hidden="true">${h(review.reviewer.charAt(0).toUpperCase())}</span><div><strong>${h(review.reviewer)}</strong><span>${h(review.country)}</span></div></div><p class="review-profile-label">From ${h(profile.name)}’s Fiverr profile</p><div class="review-card-bottom"><time datetime="${h(review.date)}">${h(reviewDate(review.date))}</time><a href="${h(profile.url)}" target="_blank" rel="noopener noreferrer">Read on Fiverr</a></div></article>`;
};
const reviewSection=({full=false}={})=>{
 const tag=full?'h1':'h2';
 const title=h(reviewData.headline).replace(' In their words.','<br><em>In their words.</em>');
 const selected=reviewData.reviews;
 const upwork=reviewData.upworkProfile?`<aside class="review-upwork" aria-label="Our Upwork profile"><p>Prefer to work through <strong>Upwork?</strong><span>Visit our profile and tell us about your project.</span></p><a class="text-link" href="${h(reviewData.upworkProfile)}" target="_blank" rel="noopener noreferrer">View our Upwork profile</a></aside>`:'';
 return `<section class="section reviews-section${full?' reviews-page':''}" id="client-reviews" data-review-list aria-labelledby="reviews-title"><div class="wrap">${full?crumbs([{label:'Reviews'}]):''}<div class="review-head"><div>${eyebrow('Client reviews')}<${tag} id="reviews-title">${title}</${tag}><p class="lead">${h(reviewData.intro)}</p></div><div class="review-proof"><strong>${h(reviewData.countLabel)}</strong><span>customer reviews<br>on Fiverr</span></div></div><div class="review-profiles">${reviewData.profiles.map(profile=>`<a class="review-profile" href="${h(profile.url)}" target="_blank" rel="noopener noreferrer"><div><span>${h(profile.specialty)}</span><strong>${h(profile.name)}</strong></div><div class="review-profile-score"><b>${h(profile.rating)}<span>/5</span></b><span>${h(profile.reviewCount)} reviews on Fiverr</span></div></a>`).join('')}</div><p class="review-source-note">Across our team’s two Fiverr profiles. Ratings checked <time datetime="${h(reviewData.checkedAt)}">${h(reviewDate(reviewData.checkedAt))}</time>.</p><div class="review-grid" id="reviews-grid">${selected.map((review,index)=>reviewCard(review,index>=3)).join('')}</div><div class="review-load-more"><p data-review-count class="sr-only" aria-live="polite">Showing ${Math.min(3,selected.length)} of ${selected.length} reviews</p><button type="button" class="button outline" data-review-more aria-controls="reviews-grid"${selected.length<=3?' hidden':''}>Show more reviews (${Math.max(0,selected.length-3)} remaining)</button></div><div class="review-section-foot"><p>Reviews from our team’s Fiverr profiles. Read the originals on Fiverr.</p>${full?'':link('/reviews/','Explore client reviews','text-link')}</div>${upwork}</div></section>`;
};

function sourceOnlyPreview(item){return Boolean(item?.previewRestricted||item?.previewUnavailable);}
const projectCover=p=>{
 if(!p.cover?.nodeId)return p.cover;
 const matching=(p.gallery||[]).filter(item=>item.nodeId===p.cover.nodeId);
 const restricted=matching.find(item=>item.previewRestricted);
 if(restricted)return restricted;
 if(p.cover.previewRestricted)return p.cover;
 return p.cover.previewUnavailable?matching.find(item=>!sourceOnlyPreview(item)&&item.src)||p.cover:p.cover;
};
const projectWorkTypes=p=>{
 const known=['design','development','wordpress','template'];
 const supplied=Array.isArray(p.workTypes)?[...new Set(p.workTypes.filter(type=>known.includes(type)))]:[];
 if(supplied.length)return supplied;
 return p.scope==='template'?['design','template']:p.scope==='ui-development'?['design','development']:p.scope==='ui'?['design']:['development'];
};
const projectScopeLabel=p=>{
 if(p.scope==='template')return 'UI template';
 const types=projectWorkTypes(p);
 return [types.includes('design')?'UI/UX':null,types.includes('development')?'Development':null,types.includes('wordpress')?'WordPress':null].filter(Boolean).join(' + ');
};
const websiteStatus=p=>['available','expired','review','design-only'].includes(p.websiteStatus)?p.websiteStatus:p.website?'review':'design-only';
const websiteStatusLabel=p=>p.deliveryStatus==='design-review'?'Design under client review':websiteStatus(p)==='expired'?'Website expired':websiteStatus(p)==='review'?'Website under review':websiteStatus(p)==='available'?'Website available':'Design preview';
const websiteHost=p=>{try{return new URL(p.website).hostname.replace(/^www\./,'');}catch{return '';}};
const websiteAction=(p,classes='text-link')=>websiteStatus(p)==='available'?externalLink(p.website,projectWorkTypes(p).includes('development')?'View website':'View website reference',classes):'';
const websiteDetails=p=>p.website?`<div class="project-website"><span class="website-status website-status-${h(websiteStatus(p))}">${h(websiteStatusLabel(p))}</span>${websiteAction(p)}<span class="website-host">${h(websiteHost(p))}</span>${p.websiteNote?`<span class="website-note">${h(p.websiteNote)}</span>`:''}</div>`:'';
const deliveryBadge=p=>p.deliveryStatus?`<span class="project-version">${h(p.deliveryStatus==='delivered'?'Delivered':p.deliveryStatus==='design-review'?'In progress':p.deliveryStatus)}</span>`:'';
const projectBadges=(p,compact=false)=>`<div class="project-badges"><span class="project-scope">${h(projectScopeLabel(p))}</span>${(p.stack||[]).filter(tech=>!(projectWorkTypes(p).includes('wordpress')&&tech.toLowerCase()==='wordpress')).slice(0,compact?3:Infinity).map(tech=>`<span class="project-stack">${h(tech)}</span>`).join('')}${deliveryBadge(p)}${p.versionLabel?`<span class="project-version">${h(p.versionLabel)}</span>`:''}${['expired','review'].includes(websiteStatus(p))?`<span class="website-status website-status-${h(websiteStatus(p))}">${h(websiteStatusLabel(p))}</span>`:''}</div>`;
const imageryCaption=p=>projectCover(p)?.previewType==='imagery'?`<p class="project-imagery-caption">${h(projectCover(p).label||'Image from the project website')}</p>`:'';
const workVisual=(p,priority=false)=>{
 const cover=projectCover(p);
 if(sourceOnlyPreview(cover))return `<div class="work-cover source-cover"><span class="design-source-symbol" aria-hidden="true"></span><p>Preview available in Figma</p><span class="design-cover-label">${p.scope==='template'?'UI template':'UI/UX Design'}</span></div>`;
 if(cover?.src)return `<div class="work-cover supplied-cover${projectWorkTypes(p).includes('design')?' design-cover':''}"><img src="${h(cover.src)}" alt="${h(cover.alt||p.name+' project visual')}" width="${Number(cover.width)}" height="${Number(cover.height)}" loading="${priority?'eager':'lazy'}" decoding="async" style="object-position:${h(cover.objectPosition||'50% 0%')}">${cover.previewType==='imagery'?'<span class="design-cover-label">Project imagery</span>':cover.previewType==='website'?'<span class="design-cover-label">Website UI</span>':projectWorkTypes(p).includes('design')?`<span class="design-cover-label">${p.scope==='template'?'UI template':'UI/UX Design'}</span>`:''}</div>`;
 if(p.slug==='footstep-online')return `<div class="work-cover footstep-cover"><img src="/assets/footstep-campaign.webp" alt="Footstep Online footwear campaign on sunlit outdoor steps" width="1536" height="1024" loading="${priority?'eager':'lazy'}"><div class="cover-caption"><strong>footstep.</strong><span>Made to move.</span></div></div>`;
 if(p.slug==='dna-digital-consultancy')return `<div class="work-cover dna-cover"><img src="/assets/dna-project.webp" alt="DNA Digital Consultancy website portfolio visual, shown on desktop and mobile" width="1421" height="800" loading="${priority?'eager':'lazy'}"></div>`;
 return `<div class="work-cover project-cover-fallback"><span class="project-cover-kicker">${h(projectScopeLabel(p))}</span><strong>${h(p.name)}</strong><span>Explore the project</span></div>`;
};
function workCard(p,featured=false){
 const types=projectWorkTypes(p),design=types.includes('design');
 const screenCount=previewImages(p).length;
 return `<a class="work-card${featured?' featured':''}${design?' design-card':''}" href="/work/${h(p.slug)}/" data-filter-item="${h(types.join(' '))}" data-search-text="${h([p.name,p.category,p.summary,projectScopeLabel(p),...(p.stack||[]),p.versionLabel||'',...types].join(' '))}">${workVisual(p)}<div class="work-meta"><div>${featured?eyebrow('Featured work · Ecommerce'):''}<h3>${h(p.name)}</h3><p>${h(featured?p.summary:p.category)}</p>${projectBadges(p,true)}${screenCount>1?`<span class="work-screen-count">${screenCount} screens &amp; variations</span>`:''}${featured?'<span class="text-link">Explore the project</span>':''}</div></div></a>`;
}
const externalLink=(url,label,classes='text-link')=>/^https?:\/\//i.test(url||'')?`<a class="${classes}" href="${h(url)}" target="_blank" rel="noopener noreferrer">${h(label)}<span class="sr-only"> (opens in a new tab)</span></a>`:'';
const previewImages=p=>{
 const unique=new Map();
 const items=[...(p.cover&&(sourceOnlyPreview(p.cover)||p.cover.fullSrc||p.cover.previewType!=='imagery')?[p.cover]:[]),...(Array.isArray(p.gallery)?p.gallery:[])];
 const restricted=new Map(items.filter(item=>item?.previewRestricted&&item.nodeId).map(item=>[item.nodeId,item]));
 const available=new Map(items.filter(item=>item?.nodeId&&item.src&&!sourceOnlyPreview(item)).map(item=>[item.nodeId,item]));
 for(const raw of items){
  const item=restricted.get(raw?.nodeId)||(raw?.previewUnavailable&&available.get(raw.nodeId))||raw;
  if(!item||typeof item!=='object'||(sourceOnlyPreview(item)?!item.nodeId:!item.src))continue;
  const key=sourceOnlyPreview(item)?'source:'+item.nodeId:item.fullSrc||item.src;
  if(!unique.has(key))unique.set(key,{...item});
  else{
   const first=unique.get(key);
   for(const field of ['group','label','nodeId','sourceName','device','fullWidth','fullHeight','figmaUrl','previewType'])if(item[field])first[field]=item[field];
  }
 }
 return [...unique.values()];
};
const previewLabel=(item,index)=>item.label||item.sourceName||(index===0?'Design overview':'Design screen '+(index+1));
const previewGroup=item=>item.group||'Design variations';
function designPreview(p,item,index,hero=false){
 const label=previewLabel(item,index),group=previewGroup(item);
 const mobile=item.device==='mobile'||(Number(item.fullWidth)>0&&Number(item.fullWidth)<=600&&Number(item.fullHeight)>Number(item.fullWidth));
 const visual=sourceOnlyPreview(item)?`<div class="design-source-preview"><span class="design-source-symbol" aria-hidden="true"></span><p>Preview available in Figma</p>${externalLink(item.figmaUrl||p.figmaUrl,'View source design','button outline')}</div>`:`<a class="design-preview-link" href="${h(item.fullSrc||item.src)}" data-design-preview data-preview-src="${h(item.fullSrc||item.src)}" data-preview-alt="${h(item.alt||p.name+' — '+label)}" data-preview-label="${h(label)}" data-preview-group="${h(group)}" aria-label="Open ${h(p.name+' — '+label)}"><img src="${h(item.src)}" alt="${h(item.alt||p.name+' — '+label)}" width="${Number(item.width)}" height="${Number(item.height)}" loading="${hero?'eager':'lazy'}" decoding="async" style="object-position:${h(item.objectPosition||'50% 0%')}"><span class="design-open">Open preview</span></a>`;
 return `<figure class="design-preview${hero?' design-preview-hero':''}${mobile?' design-preview-mobile':''}"${hero?'':` data-variant-card data-variant-kind="${sourceOnlyPreview(item)?'source':'image'}" data-variant-group="${h(group)}" data-variant-search="${h([label,group,item.sourceName||''].join(' '))}"`}>${visual}<figcaption><span class="design-preview-caption"><strong>${h(label)}</strong><span>${h(group)}</span></span><span>${item.previewType==='website'?'Website UI':p.scope==='template'?'UI template':'UI/UX Design'}</span></figcaption></figure>`;
}
function designGallery(p){
 const images=previewImages(p);
 if(images.length<2)return '';
 const groups=[...new Set(images.map(previewGroup))];
 const pageTypes=new Set(images.map(item=>item.pageType||'homepage'));
 const galleryTitle=pageTypes.size>1?'Homepages &amp;<br><em>dashboards.</em>':pageTypes.has('dashboard')?'The dashboard.<br><em>Different directions.</em>':'The homepage.<br><em>Different directions.</em>';
 const galleryFocus=pageTypes.size>1?'homepage and dashboard':pageTypes.has('dashboard')?'dashboard':'homepage';
 return `<section class="section surface-alt project-variants" id="design-variants" data-project-gallery data-variant-page-size="12" aria-labelledby="variant-heading"><div class="wrap"><div class="section-head"><div>${eyebrow('Explore this project')}<h2 id="variant-heading">${galleryTitle}</h2></div><p class="lead">Explore the ${galleryFocus} variations for ${h(p.name)}. Open a design for a closer look.</p></div><div class="variant-controls" data-variant-controls hidden><label class="variant-group-control"><span>Screen group</span><select data-variant-group-select><option value="">All screens (${images.length})</option>${groups.map(group=>`<option value="${h(group)}">${h(group)} (${images.filter(item=>previewGroup(item)===group).length})</option>`).join('')}</select></label><label class="variant-type-control"><span>Preview type</span><select data-variant-type-select><option value="">All screens</option><option value="image">Image previews</option><option value="source">Figma sources</option></select></label><label class="variant-search-control"><span>Search this project</span><input type="search" data-variant-search placeholder="Search pages, versions or screens" autocomplete="off"></label></div><div class="variant-gallery-status"><p data-variant-status aria-live="polite">${images.length} ${images.length===1?'screen':'screens'}</p><span>Grouped within this project</span></div><div class="design-gallery">${images.map((item,i)=>designPreview(p,item,i)).join('')}</div><div class="variant-empty" data-variant-empty hidden><h3>No screens match that search.</h3><p>Try another page name or show every screen in this project.</p><button class="button outline" data-variant-reset type="button">Show all screens</button></div><div class="variant-more" data-variant-more-wrap hidden><button class="button outline" data-variant-more type="button">Show more screens</button></div></div></section>`;
}
function designViewer(p){
 const first=previewImages(p).find(item=>!sourceOnlyPreview(item)&&item.src);
 if(!first)return '';
 return `<dialog class="design-viewer" id="design-viewer" aria-labelledby="design-viewer-title"><div class="design-viewer-shell"><header class="design-viewer-head"><div><p class="design-viewer-kicker">Project screen</p><h2 id="design-viewer-title">${h(p.name)}</h2></div><button class="design-viewer-close" type="button" data-preview-close aria-label="Close design preview" autofocus>${icon('close')}</button></header><div class="design-viewer-toolbar"><div class="design-viewer-paging"><button type="button" data-preview-prev aria-label="Previous design preview">Previous</button><span data-preview-counter aria-live="polite"></span><button type="button" data-preview-next aria-label="Next design preview">Next</button></div><label class="design-viewer-jump"><span class="sr-only">Jump to screen</span><select data-preview-jump aria-label="Jump to screen"></select></label><div class="design-viewer-actions"><button type="button" data-preview-zoom aria-pressed="false">Full size</button><a data-preview-original href="${h(first.fullSrc||first.src)}" target="_blank" rel="noopener noreferrer">Open image<span class="sr-only"> in a new tab</span></a></div></div><div class="design-viewer-canvas" data-preview-canvas tabindex="0" role="region" aria-label="Design image. Scroll to explore the page, or use Full size to inspect the details."><p class="design-viewer-loading" data-preview-loading role="status" hidden>Loading design preview…</p><img data-preview-image alt="" hidden><p class="design-viewer-error" data-preview-error hidden>This preview could not load. Use Open image to view the original file.</p></div><footer class="design-viewer-foot"><p data-preview-label></p><span data-preview-scope>Image previews</span></footer></div></dialog>`;
}
const designHomeSection=()=>{
 const featuredDesigns=designProjects.filter(p=>projectWorkTypes(p).includes('design')).slice(0,3);
 return featuredDesigns.length?`<section class="section design-home"><div class="wrap"><div class="section-head"><div>${eyebrow('From our design portfolio')}<h2>Ideas, made<br><em>visible.</em></h2></div><div><p class="lead">Browse homepage and dashboard designs, from the first impression to the finer details.</p>${link('/work/?type=design','Explore all designs','text-link')}</div></div><div class="design-home-grid">${featuredDesigns.map(p=>workCard(p)).join('')}</div></div></section>`:'';
};
const articleCover=(article,index)=>`<div class="article-cover ${index===1?'rethink':index===2?'automate':'brief'}" aria-hidden="true">${index===1?'<div class="rethink-shape"></div>':index===2?'<div class="automation-shape"><i></i><i></i><i></i></div>':'<div class="sheet"><b>Aa.</b><i></i><i></i><i></i></div>'}</div>`;
const articleCards=(articles=data.journal)=>`<div class="article-grid">${articles.map(a=>{const i=data.journal.indexOf(a);return `<a class="article-card" href="/blog/${a.slug}" data-filter-item="${h(a.category.toLowerCase())}">${articleCover(a,i)}<div class="article-meta">${h(a.category)} · 3 min read</div><h3>${h(a.title)}</h3><p>${h(a.excerpt)}</p><span class="text-link">Read the guide</span></a>`;}).join('')}</div>`;
const pageHero=(title,intro,kicker,items)=>`<section class="page-hero"><div class="wrap">${crumbs(items)}${eyebrow(kicker)}<h1>${h(title)}</h1><p class="lead">${h(intro)}</p></div></section>`;

function render({route,title,description,kind='home',body,home=false,breadcrumb=[],noindex=false,socialImage=null}){
 const canonical=base+route;
 const shareImage=socialImage?(socialImage.startsWith('/')?base+socialImage:socialImage):base+'/assets/ap-tech-logo-dark.png';
 const schema=[{'@context':'https://schema.org','@type':'Organization',name:'AP Tech Agency',url:base,email:'info@aptechagency.com',logo:base+'/assets/ap-tech-logo-dark.png'}];
 if(breadcrumb.length) schema.push({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{name:'Home',url:'/'},...breadcrumb].map((b,i)=>({'@type':'ListItem',position:i+1,name:b.name,item:base+b.url}))});
 const html=`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="theme-color" content="#556B2F"><script>(()=>{let t='light';try{if(localStorage.getItem('ap-tech-theme')==='dark')t='dark'}catch{}document.documentElement.dataset.theme=t})();</script><title>${h(title)} | AP Tech Agency</title><meta name="description" content="${h(description)}">${noindex?'<meta name="robots" content="noindex">':''}<link rel="canonical" href="${canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="AP Tech Agency"><meta property="og:title" content="${h(title)}"><meta property="og:description" content="${h(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${h(shareImage)}"><meta name="twitter:card" content="${socialImage?'summary_large_image':'summary'}"><link rel="icon" href="/assets/ap-tech-symbol-dark.png" type="image/png"><link rel="preload" href="/assets/manrope.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/site.css?v=all-service-motion-1"><link rel="stylesheet" href="/brand-cursor.css"><link rel="stylesheet" href="/service-packages.css?v=design-system-1"><link rel="stylesheet" href="/assets/support.css"><link rel="stylesheet" href="/livechat-adapter.css?v=original-font-1"><script type="application/ld+json">${JSON.stringify(schema).replaceAll('<','\\u003c')}</script><link rel="stylesheet" href="/hero-demo.css?v=classic-calls-1"></head><body id="top" data-ap-cursor><a class="skip-link" href="#main">Skip to content</a>${dock(kind)}${home?'':masthead(false)}<main id="main">${body}</main>${footer()}${controls()}<div id="ap-support" class="ap-support" data-whatsapp="8801799664826"></div><script src="/assets/support.js" defer></script><script src="/livechat-voice.js?v=realtime-voice-3" defer></script><script src="/site.js?v=finder-choices-1" defer></script><script src="/service-packages.js?v=1" defer></script><script src="/marketing.js?v=1" defer></script><script src="/brand-cursor.js" defer></script><script src="/hero-demo.js?v=1" defer></script></body></html>`;
 const target=route==='/404.html'?path.join(dist,'404.html'):path.join(dist,route,'index.html');
 fs.mkdirSync(path.dirname(target),{recursive:true});fs.writeFileSync(target,html);
 if(!noindex)routes.push({route,title,description});
}

